    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t, r;
    cin >> t >> r;

    int lastDigit = t % 10;
    int current = lastDigit;
    int count = 1;

    while (current != 0 && current != r) {
        current = (current + lastDigit) % 10;
        ++count;
    }

    cout << count << '\n';
    return 0;
}

